}

.tableContainer {
  display: block;
  /*margin-left: auto;*/
  /*margin-right: auto;*/
  /*margin-top: auto;*/
  /*margin-left: 5px;*/
  /*margin-right: auto;*/
  width: 95%;
}

.skeletonTableLoader {
  /*margin-left: 2.5%;*/
}

.appShell {
  min-height: 100vh;
}

header {
  text-align: center;
  font-family: "Lucida Console", "Courier New", monospace;
  margin-bottom: 0.75rem;
  font-size: clamp(1.75rem, 3.5vw, 2.5rem);
  line-height: 1.1;
}

.borderlessHeader {
  border: none;
  margin-bottom: 0;
}

.pageSection {
  width: min(100%, 76rem);
  margin: 0 auto;
  padding: clamp(1rem, 3vw, 2rem);
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.bigCustomButton {
  padding: clamp(1.5rem, 5vw, 3rem);
  margin: 5px;
  width: 100%;
  min-height: clamp(8rem, 22vw, 12rem);
  white-space: normal;
}

.startButtonPosition {
  width: 100%;
  padding: clamp(1rem, 6vw, 4rem) 0;
}

.drawerLi {
  padding: 10px;
}

.drawerLi:hover {
  color: #97d8c4;
}

.playerBox {
  background-color: #046865;
  color: white;
  padding: 0.75rem;
  min-height: 140px;
  max-width: 100%;
  border-radius: 20px;
  text-align: center;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 0.5rem;
}

.endGameButtonsContainers {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  justify-content: center;
}

.tableContainer {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  width: 100%;
}

.tableScroll {
  width: 100%;
  overflow-x: auto;
  overflow-y: hidden;
  -webkit-overflow-scrolling: touch;
  padding-bottom: 0.5rem;
}

.gameActionBar {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  align-items: center;
  justify-content: space-between;
}

.helperText {
  color: #4a5568;
  font-size: 0.95rem;
}

.statsCard {
  height: 100%;
}

@media (max-width: 48rem) {
  .pageSection {
    padding: 1rem;
    gap: 0.875rem;
  }

  .endGameButtonsContainers {
    flex-direction: column;
  }

  .endGameButtonsContainers > * {
    width: 100%;
  }

  .endGameButtonsContainers button {
    width: 100%;
  }
}

