import {useParams} from "react-router-dom";
import {Heading, Spinner, Text, Tooltip, VStack} from "@chakra-ui/react";
import {useEffect, useState} from "react";
import axios from "axios";
import {statsGetRequest, user} from "../../Constants";
import {calculateAverage} from "../../Utils/calculateAverage";
import {findMaxValue} from "../../Utils/findMaxValue";
import {Radar} from "./Visuals/Radar/Radar";

export const PlayerStats = () => {
    const { player } = useParams()
    const [loading, setLoading] = useState<boolean>(true);
    const [stats, setStats] = useState<statsGetRequest>();
    const customLabels = {accuracy:"Measures how often you correctly predicted the right number of tricks. It tells you the proportion of correct calls against all the calls you made in the game", precision:"Measures how consistently you made a correct call. High precision indicates that your predictions are close to each other, even if they might not be close to the correct call", sensitivity:"Measures the completeness of your predictions. High sensitivity means that you had few and possibly unlucky incorrect calls", score:"It combines all of the above into a single metric that represents your overall performance for this game"}
    const bestCall = findMaxValue(stats?.F1Score)

    useEffect(() => {
        const getStatsAsync = async ()=> {
            setLoading(true)
            const stats = await getConfusionMatrix()
            setStats(stats)
            setLoading(false)
        }
        getStatsAsync().catch(console.error)
    }, []);

    const getConfusionMatrix = async (): Promise<statsGetRequest> => {
        try {
            const resp = await axios.get(`/stats/${player}`);
            return resp.data;
        } catch (error) {
            console.log("error: ", error)
            throw error
        }
    }
    const radarLegend = []
    console.log(stats, "<<stats")
    const radarData = stats?.precision.map((p,index)=> {
        const name = index + "-Calls"
        radarLegend.push(name)
        // @ts-ignore
        return {precision:p, accuracy: stats?.accuracy, recall: stats?.recall[index], name:name}
    })

    return  <div>
        <Heading>{player}</Heading>
        {
            loading ? <Spinner thickness='5px' speed='0.65s' emptyColor='brand.200' color='brand.100' size='xl'/> :
                <div>
                    <VStack>
                        <Text>Overall</Text>
                        <Tooltip label={customLabels.accuracy} placement='left'>
                            <Text>{`Accuracy: ${stats?.accuracy}`}</Text>
                        </Tooltip>
                        <Tooltip label={customLabels.precision} placement='left'>
                            <Text>{`Precision: ${calculateAverage(stats?.precision)}`}</Text>
                        </Tooltip>
                        <Tooltip label={customLabels.sensitivity} placement='left'>
                            <Text>{`Sensitivity: ${calculateAverage(stats?.recall)}`}</Text>
                        </Tooltip>
                        <Tooltip label={customLabels.score} placement='left'>
                            <Text>{`Score: ${calculateAverage(stats?.F1Score)}`}</Text>
                        </Tooltip>
                    </VStack>
                    <Text>{`Your best call is: ${bestCall.maxIndex} calls with a score of: ${bestCall.max}`}</Text>
                    <Radar data={radarData} width={300} height={300}/>
                </div>
        }
    </div>
}

import {useParams} from "react-router-dom";
import {Box, Center, Heading, Spinner, Text, Tooltip, useBreakpointValue, VStack} from "@chakra-ui/react";
import {useEffect, useState} from "react";
import {statsGetRequest} from "../../Constants";
import {calculateAverage} from "../../Utils/calculateAverage";
import {findMaxValue} from "../../Utils/findMaxValue";
import {Radar} from "./Visuals/Radar/Radar";
import api from "../../api";

export const PlayerStats = () => {
    const { player } = useParams()
    const [loading, setLoading] = useState<boolean>(true);
    const [stats, setStats] = useState<statsGetRequest>();
    const customLabels = {accuracy:"Measures how often you correctly predicted the right number of tricks. It tells you the proportion of correct calls against all the calls you made in the game", precision:"Measures how consistently you made a correct call. High precision indicates that your predictions are close to each other, even if they might not be close to the correct call", sensitivity:"Measures the completeness of your predictions. High sensitivity means that you had few and possibly unlucky incorrect calls", score:"It combines all of the above into a single metric that represents your overall performance for this game"}
    const bestCall = findMaxValue(stats?.F1Score)
    const radarSize = useBreakpointValue({base: 220, sm: 260, md: 320}) ?? 260

    useEffect(() => {
        const getConfusionMatrix = async (): Promise<statsGetRequest> => {
            try {
                const resp = await api.get(`/stats/${player}`);
                return resp.data;
            } catch (error) {
                console.log("error: ", error)
                throw error
            }
        }

        const getStatsAsync = async ()=> {
            setLoading(true)
            const stats = await getConfusionMatrix()
            setStats(stats)
            setLoading(false)
        }
        getStatsAsync().catch(console.error)
    }, [player]);

    const radarLegend = []
    console.log(stats, "<<stats")
    const radarData = stats?.precision.map((p: number, index: number)=> {
        const name = index + "-Calls"
        radarLegend.push(name)
        // @ts-ignore
        return {precision:p, accuracy: stats?.accuracy, recall: stats?.recall[index], name:name}
    })

    return  <Box className={'pageSection'}>
        <Heading textAlign={'center'}>{player}</Heading>
        {
            loading ? <Center py={8}><Spinner thickness='5px' speed='0.65s' emptyColor='brand.200' color='brand.100' size='xl'/></Center> :
                <Box>
                    <VStack>
                        <Text>Overall</Text>
                        <Tooltip label={customLabels.accuracy} placement='left'>
                            <Text>{`Accuracy: ${stats?.accuracy}`}</Text>
                        </Tooltip>
                        <Tooltip label={customLabels.precision} placement='left'>
                            <Text>{`Precision: ${calculateAverage(stats?.precision)}`}</Text>
                        </Tooltip>
                        <Tooltip label={customLabels.sensitivity} placement='left'>
                            <Text>{`Sensitivity: ${calculateAverage(stats?.recall)}`}</Text>
                        </Tooltip>
                        <Tooltip label={customLabels.score} placement='left'>
                            <Text>{`Score: ${calculateAverage(stats?.F1Score)}`}</Text>
                        </Tooltip>
                    </VStack>
                    <Text mt={6} textAlign={'center'}>{`Your best call is: ${bestCall.maxIndex} calls with a score of: ${bestCall.max}`}</Text>
                    <Center mt={4} overflowX={'auto'}>
                        <Radar data={radarData} width={radarSize} height={radarSize}/>
                    </Center>
                </Box>
        }
    </Box>
}

import {statsGetRequest, user} from "../../Constants";
import axios from "axios";
import {Avatar, Badge, Box, Button, GridItem, Heading, Spinner, Text} from "@chakra-ui/react";
import React, {useEffect, useState} from "react";
import {useNavigate} from "react-router-dom";
import api from "../../api";

export const Stats = () => {
    const [players, setPlayers] = useState<string[]>([])
    const [loading, setLoading] = useState(true)
    const navigate = useNavigate()

    useEffect(() => {
        const getPlayerAsync = async () => {
            setLoading(true)
            const users = await getPlayersNames()
            const names = users.map(u => u.username)
            setPlayers(names)
            setLoading(false)
        }
        getPlayerAsync().catch(console.error)
    }, []);
    const getPlayersNames = async (): Promise<user[]> => {
        try {
            const resp = await api.get("/users");
            return resp.data;
        } catch (error) {
            console.log(error)
            throw error
        }
    }
    const HandleBadgeClick = (player: string) => {
        navigate(`/stats/${player}`)
    }
    return <div>
        <Heading>Stats</Heading>
        <Box maxW={900}>
            <p>Welcome to the -not that nerdy- stats page!</p>
            <p>Here you can view general information about the game and about individual performances as well as sneaky
                rivalries and maaaaybe find your biggest weakness... Click on a player to see</p>
        </Box>
        {loading ? <Spinner thickness='5px' speed='0.65s' emptyColor='brand.200' color='brand.100' size='xl'/> :
            players.map((player, index) => {
                return (
                    <Box onClick={() => HandleBadgeClick(player)}
                         style={{display: "inline-block", margin: 10, cursor: "pointer"}} bg={'teal'} p={4}
                         color={'white'} height={170} maxW={100} borderRadius={20}>
                        <Badge borderRadius='full' px='2' colorScheme='teal'>{`Player ${index}`}</Badge>
                        <p>{player}</p>
                        <Avatar bg='teal.500'/>
                    </Box>
                )
            })}
    </div>
}

import {user} from "../../Constants";
import {Avatar, Badge, Box, Center, Heading, SimpleGrid, Spinner, Stack, Text} from "@chakra-ui/react";
import React, {useEffect, useState} from "react";
import {useNavigate} from "react-router-dom";
import api from "../../api";

export const Stats = () => {
    const [players, setPlayers] = useState<string[]>([])
    const [loading, setLoading] = useState(true)
    const navigate = useNavigate()

    useEffect(() => {
        const getPlayerAsync = async () => {
            setLoading(true)
            const users = await getPlayersNames()
            const names = users.map(u => u.username)
            setPlayers(names)
            setLoading(false)
        }
        getPlayerAsync().catch(console.error)
    }, []);
    const getPlayersNames = async (): Promise<user[]> => {
        try {
            const resp = await api.get("/users");
            return resp.data;
        } catch (error) {
            console.log(error)
            throw error
        }
    }
    const HandleBadgeClick = (player: string) => {
        navigate(`/stats/${player}`)
    }
    return <Box className={'pageSection'}>
        <Heading textAlign={'center'}>Stats</Heading>
        <Stack spacing={3} maxW={'3xl'}>
            <Text>Welcome to the -not that nerdy- stats page!</Text>
            <Text>
                Here you can view general information about the game and about individual performances as well as sneaky
                rivalries and maybe find your biggest weakness. Tap a player to dig in.
            </Text>
        </Stack>
        {loading ? (
            <Center py={8}>
                <Spinner thickness='5px' speed='0.65s' emptyColor='brand.200' color='brand.100' size='xl'/>
            </Center>
        ) : (
            <SimpleGrid minChildWidth={{base: '9rem', md: '10rem'}} spacing={4}>
                {players.map((player: string, index: number) => {
                    return (
                        <Box
                            key={`${player}-${index}`}
                            onClick={() => HandleBadgeClick(player)}
                            cursor={'pointer'}
                            bg={'teal'}
                            p={4}
                            color={'white'}
                            minH={'170px'}
                            borderRadius={20}
                            display={'flex'}
                            flexDirection={'column'}
                            justifyContent={'center'}
                            alignItems={'center'}
                            gap={3}
                            className={'statsCard'}
                        >
                            <Badge borderRadius='full' px='2' colorScheme='teal'>{`Player ${index + 1}`}</Badge>
                            <Text textAlign={'center'} fontWeight={'semibold'} noOfLines={2}>{player}</Text>
                            <Avatar bg='teal.500'/>
                        </Box>
                    )
                })}
            </SimpleGrid>
        )}
    </Box>
}

import * as d3 from 'd3';
import {AxisConfig, INNER_RADIUS, RadarGrid} from './RadarGrid';
import {HStack, VStack} from "@chakra-ui/react";

export type Variable = "accuracy" | "precision" | "recall"

type DataItem<T extends string> = {
    [key in T]: number
} & {
    name: string
}

export type Data = DataItem<Variable>[]

const MARGIN = 30;
const COLORS = [
    '#ad00ff',
    '#ff004a',
    '#ff00f2',
];

type YScale = d3.ScaleRadial<number, number, never>;

type RadarProps = {
    width: number;
    height: number;
    data?: Data;
    legend?: string[];
    axisConfig?: AxisConfig[];
};
export const Radar = ({width, height, data, axisConfig, legend}: RadarProps) => {
    const outerRadius = Math.min(width, height) / 2 - MARGIN;
        console.log(data)

    if(!data) {
        return <div></div>
    }
    axisConfig = axisConfig ?? [{ name: 'accuracy', max: 1 },{ name: 'precision', max: 1 },{ name: 'recall', max: 1 }]
    // The x scale provides an angle for each variable of the dataset
    const allVariableNames = axisConfig.map((axis) => axis.name);
    const xScale = d3
        .scaleBand()
        .domain(allVariableNames)
        .range([0, 2 * Math.PI]);

    // Compute the y scales: 1 scale per variable.

    // Provides the distance to the center.
    let yScales: { [name: string]: YScale } = {};
    axisConfig.forEach((axis) => {
        yScales[axis.name] = d3
            .scaleRadial()
            .domain([0, axis.max])
            .range([INNER_RADIUS, outerRadius]);
    });

    // Color Scale
    const allGroups = data.map((d) => d.name);
    const colorScale = d3.scaleOrdinal<string>().domain(allGroups).range(COLORS);

    // Compute the main radar shapes, 1 per group
    const lineGenerator = d3.lineRadial();

    const allLines = data.map((series, i) => {
        // @ts-ignore
        const allCoordinates = axisConfig.map((axis) => {
            const yScale = yScales[axis.name];
            const angle = xScale(axis.name) ?? 0; // I don't understand the type of scalePoint. IMO x cannot be undefined since I'm passing it something of type Variable.
            const radius = yScale(series[axis.name]);
            const coordinate: [number, number] = [angle, radius];
            return coordinate;
        });

        // To close the path of each group, the path must finish where it started
        // so add the last data point at the end of the array
        allCoordinates.push(allCoordinates[0]);
        const d = lineGenerator(allCoordinates);
        if (!d) {
            return;
        }
        return (
            <path
                key={i}
                d={d}
                stroke={colorScale(series.name)}
                strokeWidth={3}
                fill={colorScale(series.name)}
                fillOpacity={0.1}
            />
        );
    });
    //Legend
    var keys = legend ?? ["1 Call", "2 Calls", "3 Calls"];

    const Svg = d3.select("#my_radar");
    // Create a group for the legend
    const legendGroup = Svg.append("g")
        .attr("transform", "translate(10, 10)"); // Adjust translate values as needed

    // Add one dot in the legend for each name
    legendGroup.selectAll("mydots")
        .data(keys)
        .enter()
        .append("circle")
        .attr("cx", 10)
        .attr("cy", (d, i) => 10 + i * 20) // Adjust spacing as needed
        .attr("r", 5) // Adjust radius as needed
        .style("fill", d => colorScale(d) as string);

    // Add one text label in the legend for each name
    legendGroup.selectAll("mylabels")
        .data(keys)
        .enter()
        .append("text")
        .attr("x", 20) // Adjust text distance from circles
        .attr("y", (d, i) => 10 + i * 20) // Adjust spacing as needed
        .style("fill", d => colorScale(d) as string)
        .text(d => d)
        .style("alignment-baseline", "middle");

    return (
        <div>
            <HStack>
            <svg width={width} height={height}>
                <g transform={'translate(' + width / 2 + ',' + height / 2 + ')'}>
                    <RadarGrid
                        outerRadius={outerRadius}
                        xScale={xScale}
                        axisConfig={axisConfig}
                    />
                    {allLines}
                </g>
            </svg>
            <svg id={"my_radar"} height='100' width='100'/>
            </HStack>
        </div>
    );
};

