            setPlayerNames(users)
        }
        const fertchCallsAndScores = async () => {
            setLoading(true)
            const calls = await getPlayersCalls()
            const tricks = await getPlayersTricks()
            const scores = await getScores()
            setPlayerCalls(calls)
            setPlayerTricks(tricks)
            setPlayerScores(scores)
            setLoading(false)
        }
        fetchUsersAndDealers().catch(console.error)
        fertchCallsAndScores().catch(console.error)
    }, []);

    const updateUsersAndScores = async () => {
        // setLoading(true)
        getPlayersCalls().then((calls: callsGetRequest[]) => {
            setPlayerCalls(calls)
        })
        getPlayersTricks().then((tricks: tricksGetRequest[]) => {
            setPlayerTricks(tricks)
        })
        getScores().then((scores: scoresGetRequest[]) => {
            setPlayerScores(scores)
        })
        // setLoading(false)
    }
    const getPlayersCalls = async (): Promise<callsGetRequest[]> => {
        try {
            const resp = await api.get("/calls");
            return resp.data;
        } catch (error) {
            console.log(error)
            throw error
        }
    }
    const getScores = async (): Promise<scoresGetRequest[]> => {
        try {
            const resp = await api.get("/scores");
            return resp.data;
        } catch (error) {
            console.log(error)
            throw error
        }
    }
    const getPlayersTricks = async (): Promise<tricksGetRequest[]> => {
        try {
            const resp = await api.get("/tricks");
            return resp.data;
        } catch (error) {
            console.log(error)
            throw error
        }
    }
    const getPlayersNames = async (): Promise<user[]> => {
        try {
            const resp = await api.get("/users");
            return resp.data;
        } catch (error) {
            console.log(error)
            throw error
        }
    }
    const getDealersAndCards = async (): Promise<dealerGetRequest[]> => {
        try {
            const resp = await api.get("/dealer");
            return resp.data;
        } catch (error) {
            console.log("Error in get /dealer", error)
            throw error
        }
    }
    const addCall = async (value: number, cell: cellCoords | undefined) => {
        if (cell) {
            const newCall: callsPostRequest = {roundNo: cell.roundNo, [cell.player]: value}
            const dealerRound = dealerAndCards.find((d: dealerGetRequest) => d.roundno === cell.roundNo)
            let callsRound = playerCalls?.find((c: callsGetRequest) => c.roundno === cell.roundNo)
            if (callsRound) {
                callsRound = removeKeyFromObject(callsRound, cell.player as keyof callsGetRequest)
                const roundValues = Object.values(callsRound) as Array<number | null | undefined>
                const total = roundValues.reduce((acc: number, val) => {
                    if (val == null) {
                        return -100
                    }
                    return typeof val === 'number' ? acc + val : acc
                }, -callsRound.roundno);
                if (total + value === dealerRound?.cards) {
                    return toast({
                        title: 'Call sum matches total tricks',
                        description: `Sorry can't make that call`,
                        status: 'error',
                        duration: 2000,
                        isClosable: true,
                    })
                }
            } else {
                console.log("round is undefined")
            }
            try {
                await api.post("/call", newCall)
                await updateUsersAndScores()
            } catch (error) {
                console.log(error)
                throw error
            }
        } else {
            throw ReferenceError
        }
    }
    const addTrick = async (value: number, cell: cellCoords | undefined) => {
        if (cell) {
            const newTrick: tricksPostRequest = {roundNo: cell.roundNo, [cell.player]: value}
            try {
                await api.post("/trick", newTrick)
                await updateUsersAndScores()
            } catch (error) {
                console.log(error)
                throw error
            }
            return {msg: 'success'}
        } else {
            throw ReferenceError
        }
    }
    const onClickCell = (cell: cellCoords) => {
        setSelectedCell(cell)
        if (dealerAndCards.length !== 0) {
            const dealerRow = dealerAndCards.find((d: dealerGetRequest) => d.roundno === cell.roundNo)
            setMaxTricksCallsForCell({calls: dealerRow?.cards ?? 10, tricks: dealerRow?.cards ?? 10})
        }
        onOpen()
    }
    const addDealer = async (newDealer: dealerPostRequest) => {
        try {
            await api.post("/dealer", newDealer)
            // await getDealersAndCards() too fast a request issue
        } catch (error) {
            console.log(error)
            throw error
        }
    }

    function removeKeyFromObject(obj: callsGetRequest, keyToRemove: keyof callsGetRequest) {
        const newObj = {...obj};
        delete newObj[keyToRemove as keyof callsGetRequest];
        return newObj;
    }

    return (
        <Box className={'pageSection'}>
            <header>Game screen</header>
            <div className={"tableContainer"}>
                <div className={'gameActionBar'}>
                    <Link to={'/setup'}><IconButton variant={'main'} aria-label='go back'
                                                    icon={<ArrowBackIcon/>}>Back</IconButton></Link>
                    <Link to={'/endGame'}><Button variant={'main'}>End Game</Button></Link>
                </div>
                <Text className={'helperText'}>On smaller screens, swipe horizontally to browse the score table.</Text>
                <SkeletonLoader isLoaded={!loading}>
                    <Box className={'tableScroll'}>
                        <GameTable
                            addDealer={addDealer}
                            playerNames={playerNames}
                            playerCalls={playerCalls}
                            playerTricks={playerTricks}
                            playerScores={playerScores}
                            dealersAndCards={dealerAndCards}
                            selectedCell={selectedCell}
                            onClickCell={onClickCell}
                        />
                    </Box>
                </SkeletonLoader>
                <CallsAndTricksModal isOpen={isOpen} onClose={onClose} addCall={addCall}
                                     addTrick={addTrick} selectedCell={selectedCell}
                                     setSelectedCell={setSelectedCell}
                                     maxTricksAndCalls={maxCallsTricksForCell}/>
            </div>
        </Box>
    )
}

import {
    callsGetRequest,
    dealerGetRequest,
    dealerPostRequest,
    scoresGetRequest,
    tricksGetRequest,
    user
} from "../../Constants";
import {cellCoords} from "./GameScreen";
import {Badge, Center, Circle, Select, Table, Tbody, Td, Tfoot, Th, Thead, Tr} from "@chakra-ui/react";
import React, {useEffect, useState} from "react";
import {Text} from '@chakra-ui/react'
import {ScoreBubbles} from "../../Utils/ScoreBubbles";
import {ScoreBubble} from "./ScoreBubble";
import {FlamingBadge} from "../FlamingBadge";

interface gameTableProps {
    playerNames: user[],
    playerCalls: callsGetRequest[] | undefined,
    playerTricks: tricksGetRequest[] | undefined,
    playerScores: scoresGetRequest[] | undefined,
    dealersAndCards: dealerGetRequest[],
    selectedCell: cellCoords | undefined,
    onClickCell: (cell: cellCoords) => void
    addDealer: (dealer: dealerPostRequest) => void
}

export const GameTable = (props: gameTableProps) => {
    const tricks = props.playerTricks?.sort((a, b) => a.roundno - b.roundno) ?? []
    const scores = props.playerScores?.sort((a, b) => a.roundNo - b.roundNo) ?? []
    const [totalScores, setTotalScores] = useState<number[]>(Array(props.playerNames.length))
    const [startingDealer, setStartingDealer] = useState<number>()
    const currCallsLength = props.playerCalls?.length ?? 0
    const lastRoundNo = props.dealersAndCards.slice(-1)[0] ? props.dealersAndCards.slice(-1)[0].roundno : undefined

    const backgroundColor = 'brand.100'
    const SvgContainerStyle = {
        display:"flex",
        justifyContent:"center",
        alignItems:"center",
    }

    useEffect(() => {
        if (scores.length != 0) {
            const activePlayerKeys = Object.keys(scores[0]).slice(1)
            setTotalScores(
                activePlayerKeys.map((player) =>
                    scores.reduce((acc, obj) => {
                        if (obj !== null && player !== null) {
                            return acc + (obj[player as keyof scoresGetRequest] ?? 0);
                        } else {
                            return acc;
                        }
                    }, 0))
            )
        }
    }, [props.playerTricks, props.playerCalls]);

    const onSelectDealerChange = (player: any) => {
        setStartingDealer(player)
        props.addDealer({firstToDeal: player} as dealerPostRequest)
    }

    const newRound = {
        roundno: props.playerCalls ? props.playerCalls.length + 1 : -1,
        playerNumber: Number(props.dealersAndCards[currCallsLength] ? props.dealersAndCards[currCallsLength].dealerplayer : -1),
        get dealer() {
            if (this.roundno == 1) {
                return <Select value={startingDealer} onChange={(e) => onSelectDealerChange(e.target.value)}
                               variant={'filled'} placeholder='Who deals first'>{
                    props.playerNames.map((user) => (
                        <option value={user.id}>{user.username}</option>
                    ))
                }
                </Select>
            } else {
                return props.playerNames[this.playerNumber - 1] ? props.playerNames[this.playerNumber - 1].username : <></>
            }
        },
        get card() {
            if (props.dealersAndCards) {
                if (this.roundno == 1) {
                    return 1
                } else if (props.dealersAndCards[this.roundno - 1]) {
                    return props.dealersAndCards[this.roundno - 1].cards
                } else {
                    return ""
                }
            } else {
                return "no card found"
            }
        }
    }
    return <Table variant={'striped'} style={{ position: "relative", display: "inline-block" }}>
        <Thead>
            <Tr>
                <Th>Cards</Th>
                <Th>Dealer</Th>
                {
                    props.playerNames.map((name, index) => (
                        <Th style={{textAlign: "center"}}>
                            <FlamingBadge name={index+1} streak={0}/>
                            {/*<Badge variant={'main'} colorScheme='blue' borderRadius={10}*/}
                            {/*       padding={1}>Player {index + 1}</Badge>*/}
                            <Text>{name.username}</Text>
                        </Th>
                    ))
                }
            </Tr>
        </Thead>
        <Tbody>
            {props.playerCalls?.map((roundCalls, index) => (
                <Tr>
                    {
                        Object.keys(roundCalls).map((player, indesx) => {
                            switch (player) {
                                case ('roundno'):
                                    let playerNumber = Number(props.dealersAndCards ? props.dealersAndCards[index].dealerplayer : 0)
                                    let playerName = props.playerNames[playerNumber - 1] ? props.playerNames[playerNumber - 1].username : ""
                                    return (
                                        <>
                                            <Td>{props.dealersAndCards ? props.dealersAndCards[index].cards : ""}</Td>
                                            <Td>{playerName}</Td>
                                        </>
                                    )
                                    break
                                default:
                                    return <Td bg={props.selectedCell &&
                                    props.selectedCell.roundNo === index + 1 &&
                                    props.selectedCell.player === player
                                        ? backgroundColor
                                        : undefined}>
                                        <div onClick={() => props.onClickCell({player, roundNo: index + 1})}
                                             style={{...SvgContainerStyle, cursor: "pointer", whiteSpace: "nowrap"}}>
                                            <ScoreBubbles
                                                highlighted={(index + 1 === (props.playerCalls ? props.playerCalls.length : 1))}
                                                score={(scores.length !== 0) ? (scores[index] ? scores[index][player as keyof scoresGetRequest] : "") : ""}
                                                calls={roundCalls[player as keyof callsGetRequest]}
                                                tricks={(tricks.length !== 0) ? (tricks[index] ? tricks[index][player as keyof callsGetRequest] : "") : ""}/>
                                        </div>
                                    </Td>
                            }
                        })
                    }
                </Tr>
            ))}
            <Tr>
                {(lastRoundNo == (props.playerCalls ? props.playerCalls.length : 1)) ? <></> : <>
                    <Td>{newRound.card}</Td>
                    <Td>{newRound.dealer}</Td>
                    {
                        props.playerNames?.map((user, index) => (
                            <Td bg={props.selectedCell &&
                            props.selectedCell.roundNo === (props.playerCalls ? props.playerCalls.length + 1 : 1) &&
                            props.selectedCell.player === `player${index + 1}`
                                ? backgroundColor
                                : undefined}>
                                <div onClick={() => props.onClickCell({
                                    player: `player${index + 1}`,
                                    roundNo: (props.playerCalls ? props.playerCalls.length + 1 : 1)
                                })} style={{...SvgContainerStyle, cursor: "pointer"}}>
                                    <Badge borderRadius={10} padding={1}>New round</Badge>
                                </div>
                            </Td>
                        ))
                    }
                </>}
            </Tr>
        </Tbody>
        <Tfoot>
            <Tr>
                <Th>Total:</Th>
                <Td></Td>
                {totalScores.map((value) => (
                    <Td style={{textAlign:"center"}}><ScoreBubble value={value}/></Td>
                ))}
            </Tr>
        </Tfoot>
    </Table>
}

import {
    callsGetRequest,
    dealerGetRequest,
    dealerPostRequest,
    scoresGetRequest,
    tricksGetRequest,
    user
} from "../../Constants";
import {cellCoords} from "./GameScreen";
import {Badge, Select, Table, Tbody, Td, Tfoot, Th, Thead, Tr, useBreakpointValue} from "@chakra-ui/react";
import React, {useEffect, useMemo, useState} from "react";
import {Text} from '@chakra-ui/react'
import {ScoreBubbles} from "../../Utils/ScoreBubbles";
import {ScoreBubble} from "./ScoreBubble";
import {FlamingBadge} from "../FlamingBadge";

interface gameTableProps {
    playerNames: user[],
    playerCalls: callsGetRequest[] | undefined,
    playerTricks: tricksGetRequest[] | undefined,
    playerScores: scoresGetRequest[] | undefined,
    dealersAndCards: dealerGetRequest[],
    selectedCell: cellCoords | undefined,
    onClickCell: (cell: cellCoords) => void
    addDealer: (dealer: dealerPostRequest) => void
}

export const GameTable = (props: gameTableProps) => {
    const tricks = useMemo(() => [...(props.playerTricks ?? [])].sort((a, b) => a.roundno - b.roundno), [props.playerTricks])
    const scores = useMemo(() => [...(props.playerScores ?? [])].sort((a, b) => a.roundNo - b.roundNo), [props.playerScores])
    const [totalScores, setTotalScores] = useState<number[]>(Array(props.playerNames.length))
    const [startingDealer, setStartingDealer] = useState<number>()
    const currCallsLength = props.playerCalls?.length ?? 0
    const lastRoundNo = props.dealersAndCards.slice(-1)[0] ? props.dealersAndCards.slice(-1)[0].roundno : undefined

    const backgroundColor = 'brand.100'
    const isMobile = useBreakpointValue({base: true, md: false}) ?? false
    const bubbleSize = useBreakpointValue({base: 40, md: 50}) ?? 50
    const SvgContainerStyle = {
        display:"flex",
        justifyContent:"center",
        alignItems:"center",
    }

    useEffect(() => {
        if (scores.length !== 0) {
            const activePlayerKeys = Object.keys(scores[0]).slice(1)
            setTotalScores(
                activePlayerKeys.map((player) =>
                    scores.reduce((acc, obj) => {
                        if (obj !== null && player !== null) {
                            return acc + (obj[player as keyof scoresGetRequest] ?? 0);
                        } else {
                            return acc;
                        }
                    }, 0))
            )
        }
    }, [scores]);

    const onSelectDealerChange = (player: any) => {
        setStartingDealer(player)
        props.addDealer({firstToDeal: player} as dealerPostRequest)
    }

    const newRound = {
        roundno: props.playerCalls ? props.playerCalls.length + 1 : -1,
        playerNumber: Number(props.dealersAndCards[currCallsLength] ? props.dealersAndCards[currCallsLength].dealerplayer : -1),
        get dealer() {
            if (this.roundno === 1) {
                return <Select value={startingDealer} onChange={(e: React.ChangeEvent<HTMLSelectElement>) => onSelectDealerChange(e.target.value)}
                               variant={'filled'} placeholder='Who deals first'>{
                    props.playerNames.map((user) => (
                        <option key={user.id} value={user.id}>{user.username}</option>
                    ))
                }
                </Select>
            } else {
                return props.playerNames[this.playerNumber - 1] ? props.playerNames[this.playerNumber - 1].username : <></>
            }
        },
        get card() {
            if (props.dealersAndCards) {
                if (this.roundno === 1) {
                    return 1
                } else if (props.dealersAndCards[this.roundno - 1]) {
                    return props.dealersAndCards[this.roundno - 1].cards
                } else {
                    return ""
                }
            } else {
                return "no card found"
            }
        }
    }
    return <Table variant={'striped'} size={isMobile ? 'sm' : 'md'} style={{ position: "relative", minWidth: `${Math.max(640, props.playerNames.length * (isMobile ? 120 : 160) + 180)}px` }}>
        <Thead>
            <Tr>
                <Th py={3}>Cards</Th>
                <Th py={3}>Dealer</Th>
                {
                    props.playerNames.map((name, index) => (
                        <Th key={`${name.username}-${index}`} style={{textAlign: "center"}} py={3} minW={isMobile ? '6.5rem' : '8.5rem'}>
                            <FlamingBadge name={index+1} streak={0}/>
                            <Text fontSize={isMobile ? 'xs' : 'sm'} noOfLines={2}>{name.username}</Text>
                        </Th>
                    ))
                }
            </Tr>
        </Thead>
        <Tbody>
            {props.playerCalls?.map((roundCalls, index) => (
                <Tr key={`round-${index + 1}`}>
                    {
                        Object.keys(roundCalls).map((player) => {
                            switch (player) {
                                case ('roundno'):
                                    let playerNumber = Number(props.dealersAndCards ? props.dealersAndCards[index].dealerplayer : 0)
                                    let playerName = props.playerNames[playerNumber - 1] ? props.playerNames[playerNumber - 1].username : ""
                                    return (
                                        <React.Fragment key={`round-header-${index}`}>
                                            <Td py={3}>{props.dealersAndCards ? props.dealersAndCards[index].cards : ""}</Td>
                                            <Td py={3} fontSize={isMobile ? 'xs' : 'sm'}>{playerName}</Td>
                                        </React.Fragment>
                                    )
                                default:
                                    return <Td key={`${player}-${index}`} py={2} px={isMobile ? 1 : 2} bg={props.selectedCell &&
                                    props.selectedCell.roundNo === index + 1 &&
                                    props.selectedCell.player === player
                                        ? backgroundColor
                                        : undefined}>
                                        <div onClick={() => props.onClickCell({player, roundNo: index + 1})}
                                             style={{...SvgContainerStyle, cursor: "pointer", whiteSpace: "nowrap"}}>
                                            <ScoreBubbles
                                                size={bubbleSize}
                                                highlighted={(index + 1 === (props.playerCalls ? props.playerCalls.length : 1))}
                                                score={(scores.length !== 0) ? (scores[index] ? scores[index][player as keyof scoresGetRequest] : "") : ""}
                                                calls={roundCalls[player as keyof callsGetRequest]}
                                                tricks={(tricks.length !== 0) ? (tricks[index] ? tricks[index][player as keyof callsGetRequest] : "") : ""}/>
                                        </div>
                                    </Td>
                            }
                        })
                    }
                </Tr>
            ))}
            <Tr>
                {(lastRoundNo === (props.playerCalls ? props.playerCalls.length : 1)) ? <></> : <>
                    <Td py={3}>{newRound.card}</Td>
                    <Td py={3}>{newRound.dealer}</Td>
                    {
                        props.playerNames?.map((user, index) => (
                            <Td key={`new-round-${user.id ?? index}`} py={2} px={isMobile ? 1 : 2} bg={props.selectedCell &&
                            props.selectedCell.roundNo === (props.playerCalls ? props.playerCalls.length + 1 : 1) &&
                            props.selectedCell.player === `player${index + 1}`
                                ? backgroundColor
                                : undefined}>
                                <div onClick={() => props.onClickCell({
                                    player: `player${index + 1}`,
                                    roundNo: (props.playerCalls ? props.playerCalls.length + 1 : 1)
                                })} style={{...SvgContainerStyle, cursor: "pointer"}}>
                                    <Badge borderRadius={10} padding={1} fontSize={isMobile ? '0.65rem' : '0.75rem'}>New round</Badge>
                                </div>
                            </Td>
                        ))
                    }
                </>}
            </Tr>
        </Tbody>
        <Tfoot>
            <Tr>
                <Th>Total:</Th>
                <Td></Td>
                {totalScores.map((value: number, index: number) => (
                    <Td key={`total-${index}`} style={{textAlign:"center"}} py={3}><ScoreBubble value={value}/></Td>
                ))}
            </Tr>
        </Tfoot>
    </Table>
}

