const playerNameBadge = defineStyle(()=> {
    return {
        color: 'white',
        bg: 'brand.300',
        margin: 5,
    }
})

const buttonTheme = defineStyleConfig({
    variants: {
        main: mainButton,
        secondary: secondaryButton,
        custom: addPlayerButton,
    },
})
const badgeTheme = defineStyleConfig({
    variants: {
        main: playerNameBadge,
    },
})


export const theme = extendTheme({
    styles: {
        global: {
            body: {
                bg: 'gray.50',
                color: 'gray.800',
            }
        }
    },
    colors: {
        brand: {
            100: "#046865",
            200: "#97d8c4",
            300: "#694873",
            400: "#dcccff",
            500: "#100b00",
        },
    },
    components: {
        Button: buttonTheme,
        Badge: badgeTheme
    }
})

